import { useTheme } from "../../hooks/useTheme";
import { ThemeIcon } from "./ThemeIcon";

export const ThemeToggle = () => {
  const { theme, toggleTheme } = useTheme();

  return (
    <button
      onClick={toggleTheme}
      style={{
        padding: 6,
        borderRadius: 8,
        color: "var(--text-primary)",
        bo
      }}
    >
      <ThemeIcon isDark={theme === "dark"} />
    </button>
  );
};
